BEGIN;
CREATE SEQUENCE IF NOT EXISTS logistics_lane_seq START 1;
CREATE TABLE logistics_quantity_slabs(id BIGSERIAL PRIMARY KEY,label TEXT NOT NULL UNIQUE,quantity_kg NUMERIC(12,3) NOT NULL UNIQUE CHECK(quantity_kg>0),is_active BOOLEAN DEFAULT TRUE,sort_order INTEGER DEFAULT 0);
CREATE TABLE logistics_lanes(id BIGSERIAL PRIMARY KEY,lane_code TEXT NOT NULL UNIQUE DEFAULT('LANE-'||lpad(nextval('logistics_lane_seq')::text,4,'0')),pickup_warehouse_id BIGINT REFERENCES supplier_warehouses(id) ON DELETE SET NULL,pickup_warehouse TEXT NOT NULL,pickup_district TEXT NOT NULL,pickup_pincode VARCHAR(10) NOT NULL,delivery_district TEXT NOT NULL,delivery_pincode VARCHAR(10) NOT NULL,notes TEXT,preferred_transporter_id BIGINT,vehicle_restrictions TEXT,road_conditions TEXT,appointment_requirements TEXT,seasonal_restrictions TEXT,special_instructions TEXT,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(pickup_warehouse,pickup_pincode,delivery_district,delivery_pincode));
CREATE TABLE logistics_transporters(id BIGSERIAL PRIMARY KEY,company_name TEXT NOT NULL,gst_number VARCHAR(15),pan_number VARCHAR(10),contact_person TEXT,phone_number TEXT,email TEXT,office_address TEXT,is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
ALTER TABLE logistics_lanes ADD CONSTRAINT logistics_lane_preferred_transporter_fk FOREIGN KEY(preferred_transporter_id) REFERENCES logistics_transporters(id) ON DELETE SET NULL;
CREATE TABLE logistics_transporter_documents(id BIGSERIAL PRIMARY KEY,transporter_id BIGINT NOT NULL REFERENCES logistics_transporters(id) ON DELETE CASCADE,file_name TEXT NOT NULL,file_url TEXT NOT NULL,document_type TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE logistics_quotes(id BIGSERIAL PRIMARY KEY,lane_id BIGINT NOT NULL REFERENCES logistics_lanes(id),transporter_id BIGINT NOT NULL REFERENCES logistics_transporters(id),quantity_kg NUMERIC(12,3) NOT NULL,quoted_freight_per_kg NUMERIC(14,4) NOT NULL CHECK(quoted_freight_per_kg>=0),awarded BOOLEAN DEFAULT FALSE,remarks TEXT,quoted_at TIMESTAMPTZ DEFAULT now(),created_by INTEGER REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE logistics_shipments(id BIGSERIAL PRIMARY KEY,lane_id BIGINT NOT NULL REFERENCES logistics_lanes(id),transporter_id BIGINT NOT NULL REFERENCES logistics_transporters(id),buyer_id BIGINT REFERENCES buyers(id) ON DELETE SET NULL,quantity_kg NUMERIC(12,3) NOT NULL CHECK(quantity_kg>0),freight_rate_per_kg NUMERIC(14,4) NOT NULL CHECK(freight_rate_per_kg>=0),shipment_weight_kg NUMERIC(12,3) NOT NULL CHECK(shipment_weight_kg>0),shipment_date DATE NOT NULL DEFAULT CURRENT_DATE,order_reference TEXT,invoice_number TEXT,remarks TEXT,delivery_status TEXT DEFAULT 'In Transit',delivered_at TIMESTAMPTZ,expected_delivery_at TIMESTAMPTZ,created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE logistics_cost_register(id BIGSERIAL PRIMARY KEY,shipment_id BIGINT NOT NULL UNIQUE REFERENCES logistics_shipments(id),order_reference TEXT,invoice_number TEXT,freight_cost NUMERIC(14,2) DEFAULT 0,door_delivery_charges NUMERIC(14,2) DEFAULT 0,porter_charges NUMERIC(14,2) DEFAULT 0,other_charges NUMERIC(14,2) DEFAULT 0,total_logistics_cost NUMERIC(14,2) GENERATED ALWAYS AS(COALESCE(freight_cost,0)+COALESCE(door_delivery_charges,0)+COALESCE(porter_charges,0)+COALESCE(other_charges,0)) STORED,remarks TEXT,created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE logistics_settings(id SMALLINT PRIMARY KEY DEFAULT 1 CHECK(id=1),acceptable_variance_percent NUMERIC(6,2) NOT NULL DEFAULT 10,recent_history_limit INTEGER NOT NULL DEFAULT 10,updated_at TIMESTAMPTZ DEFAULT now());
INSERT INTO logistics_settings(id) VALUES(1) ON CONFLICT DO NOTHING;
INSERT INTO logistics_quantity_slabs(label,quantity_kg,sort_order) VALUES('500 Kg',500,1),('1 MT',1000,2),('2 MT',2000,3),('3 MT',3000,4),('4 MT',4000,5),('5 MT',5000,6),('6 MT',6000,7),('7 MT',7000,8),('8 MT',8000,9),('9 MT',9000,10),('10 MT',10000,11),('12 MT',12000,12),('15 MT',15000,13),('18 MT',18000,14),('20 MT',20000,15),('25 MT',25000,16),('30 MT',30000,17),('35 MT',35000,18),('42 MT',42000,19) ON CONFLICT DO NOTHING;
CREATE INDEX idx_logistics_lane_search ON logistics_lanes(pickup_district,pickup_pincode,delivery_district,delivery_pincode);
CREATE INDEX idx_logistics_shipments_prediction ON logistics_shipments(lane_id,quantity_kg,shipment_date DESC);
CREATE INDEX idx_logistics_quotes_lane ON logistics_quotes(lane_id,quantity_kg,quoted_at DESC);
CREATE INDEX idx_logistics_transporter_shipments ON logistics_shipments(transporter_id,shipment_date DESC);
DO $$ BEGIN
 IF to_regclass('public.quotations') IS NOT NULL THEN ALTER TABLE quotations ADD COLUMN IF NOT EXISTS logistics_lane_id BIGINT REFERENCES logistics_lanes(id) ON DELETE SET NULL; ALTER TABLE quotations ADD COLUMN IF NOT EXISTS predicted_freight_per_kg NUMERIC(14,4); END IF;
 IF to_regclass('public.finance') IS NOT NULL THEN ALTER TABLE finance ADD COLUMN IF NOT EXISTS logistics_cost_id BIGINT REFERENCES logistics_cost_register(id) ON DELETE SET NULL; ALTER TABLE finance ADD COLUMN IF NOT EXISTS freight_per_kg NUMERIC(14,4); END IF;
END $$;
UPDATE roles SET permissions=jsonb_set(jsonb_set(COALESCE(permissions,'{}'::jsonb),'{modules}',COALESCE(permissions->'modules','{}'::jsonb),true),'{modules,logistics}','true',true);
COMMIT;
